// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;

    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint256 amount, address actor, address to) public {
        vm.assume(actor != address(0) && to != address(0));
        vm.assume(actor != to);
        vm.assume(actor != address(c) && to != address(c));
        amount = bound(amount, 1e18, 1e30);

        vm.prank(actor);
        c.supplyTokenTo(amount, to);

        // Rule: the caller's own credit balance is untouched by a deposit made
        // for a different beneficiary; all issued credits go to `to`.
        assertTrue(c.imBalances(actor) == 0);
    }
}

